Interprets various human-readable date formats and returns (year, month, day).
Raises ValueError for unrecognisable input.
"""

import re
from datetime import datetime

# Month name → number mapping (full and abbreviated)
_MONTH_NAMES = {
    "january": 1, "jan": 1,
    "february": 2, "feb": 2,
    "march": 3, "mar": 3,
    "april": 4, "apr": 4,
    "may": 5,
    "june": 6, "jun": 6,
    "july": 7, "jul": 7,
    "august": 8, "aug": 8,
    "september": 9, "sep": 9, "sept": 9,
    "october": 10, "oct": 10,
    "november": 11, "nov": 11,
    "december": 12, "dec": 12,
}

# Ordered list of strptime format strings to try
_STRPTIME_FORMATS = [
    # ISO / numeric
    "%Y-%m-%d",       # 2024-03-15
    "%Y/%m/%d",       # 2024/03/15
    "%Y.%m.%d",       # 2024.03.15
    "%d-%m-%Y",       # 15-03-2024
    "%d/%m/%Y",       # 15/03/2024
    "%d.%m.%Y",       # 15.03.2024
    "%m-%d-%Y",       # 03-15-2024
    "%m/%d/%Y",       # 03/15/2024
    "%m.%d.%Y",       # 03.15.2024
    # Written month
    "%B %d, %Y",      # March 15, 2024
    "%B %d %Y",       # March 15 2024
    "%b %d, %Y",      # Mar 15, 2024
    "%b %d %Y",       # Mar 15 2024
    "%d %B %Y",       # 15 March 2024
    "%d %b %Y",       # 15 Mar 2024
    "%d %B, %Y",      # 15 March, 2024
    "%d %b, %Y",      # 15 Mar, 2024
    "%B %Y %d",       # March 2024 15  (unusual but attempt)
    # With day-of-week prefix
    "%A, %B %d, %Y",  # Friday, March 15, 2024
    "%A %B %d %Y",    # Friday March 15 2024
]


def _validate(year: int, month: int, day: int) -> tuple[int, int, int]:
    """Sanity-check ranges and return the tuple, or raise ValueError."""
    if not (1 <= month <= 12):
        raise ValueError(f"Invalid month: {month}")
    if not (1 <= day <= 31):
        raise ValueError(f"Invalid day: {day}")
    # Use datetime for full validation (handles month lengths, leap years)
    try:
        datetime(year, month, day)
    except ValueError as exc:
        raise ValueError(f"Invalid date: {year}-{month}-{day}") from exc
    return (year, month, day)


def _try_numeric_ambiguous(s: str) -> tuple[int, int, int] | None:
    """
    Handle purely numeric date strings that are ambiguous between
    DD/MM/YYYY and MM/DD/YYYY by preferring the ISO-style YYYY-MM-DD
    when the year is 4 digits, otherwise falling back to MM/DD/YYYY
    (US style) and then DD/MM/YYYY.
    """
    sep_match = re.match(r'^(\d{1,4})([-/.])(\d{1,2})\2(\d{1,4})$', s.strip())
    if not sep_match:
        return None
    a, _, b, c = int(sep_match.group(1)), sep_match.group(2), int(sep_match.group(3)), int(sep_match.group(4))

    # If first token is 4-digit year: YYYY-MM-DD
    if sep_match.group(1).__len__() == 4 or a > 31:
        # YYYY-MM-DD
        try:
            return _validate(a, b, c)
        except ValueError:
            pass

    # If last token is 4-digit year
    if sep_match.group(4).__len__() == 4 or c > 31:
        # Try MM/DD/YYYY then DD/MM/YYYY
        for month, day in [(a, b), (b, a)]:
            try:
                return _validate(c, month, day)
            except ValueError:
                continue

    return None


def parse_date(s: str) -> tuple[int, int, int]:
    """Parse a date string and return (year, month, day)."""
    if not isinstance(s, str):
        raise ValueError(f"Expected a string, got {type(s).__name__}")

    s = s.strip()
    if not s:
        raise ValueError("Empty date string")

    # 1. Try strptime formats first (handles named months unambiguously)
    for fmt in _STRPTIME_FORMATS:
        try:
            dt = datetime.strptime(s, fmt)
            return _validate(dt.year, dt.month, dt.day)
        except ValueError:
            continue

    # 2. Try numeric ambiguous formats
    result = _try_numeric_ambiguous(s)
    if result is not None:
        return result

    # 3. Try to extract month name + two numbers from a messy string
    lower = s.lower()
    for name, month_num in _MONTH_NAMES.items():
        if name in lower:
            # Remove the month name and look for two remaining integers
            remainder = re.sub(re.escape(name), " ", lower)
            nums = re.findall(r'\d+', remainder)
            if len(nums) == 2:
                a, b = int(nums[0]), int(nums[1])
                # Determine which is year and which is day
                if a > 31:  # a is year
                    try:
                        return _validate(a, month_num, b)
                    except ValueError:
                        pass
                elif b > 31:  # b is year
                    try:
                        return _validate(b, month_num, a)
                    except ValueError:
                        pass
                else:
                    # Both small: assume first is day, second is 2-digit year
                    # or try both
                    for day, year in [(a, b), (b, a)]:
                        yr = year + (2000 if year < 70 else 1900)
                        try:
                            return _validate(yr, month_num, day)
                        except ValueError:
                            continue

    # 4. Pure 8-digit number: YYYYMMDD
    digits_only = re.fullmatch(r'(\d{4})(\d{2})(\d{2})', s.strip())
    if digits_only:
        y, m, d = int(digits_only.group(1)), int(digits_only.group(2)), int(digits_only.group(3))
        try:
            return _validate(y, m, d)
        except ValueError:
            pass

    raise ValueError(f"Cannot parse date string: {s!r}")

