    g1, g3, g4 = sep_match.group(1), sep_match.group(3), sep_match.group(4)
    a, b, c = int(g1), int(g3), int(g4)

    # If first token is 4-digit year: YYYY-MM-DD
    if len(g1) == 4 or a > 31:
        try:
