def _extract_with_month_name(s: str) -> tuple | None:
    """
    Try to extract a date when the string contains a spelled-out month name.
    Returns (year, month, day) or None.
    """
    lower = s.lower()
    # Sort by length descending so "september" matches before "sep"
    for name in sorted(_MONTH_NAMES.keys(), key=len, reverse=True):
        pattern = r'\b' + re.escape(name) + r'\b'
        if re.search(pattern, lower):
            month_num = _MONTH_NAMES[name]
            # Remove the month name and look for remaining integers
            remainder = re.sub(pattern, " ", lower)
            nums = re.findall(r'\d+', remainder)
            if len(nums) >= 2:
                # Try all pairs of (num[i], num[j]) where one could be year and other day
                candidates = []
                for i in range(len(nums)):
                    for j in range(len(nums)):
                        if i == j:
                            continue
                        a, b = int(nums[i]), int(nums[j])
                        candidates.append((a, b))

                # First: look for a 4-digit year explicitly
                for a, b in candidates:
                    if a > 999:  # a is year
                        try:
                            return _validate(a, month_num, b)
                        except ValueError:
                            continue

                # Second: look for >31 as year
                for a, b in candidates:
                    if a > 31:
                        try:
                            return _validate(a, month_num, b)
                        except ValueError:
                            continue

                # Third: both small — 2-digit year
                if len(nums) == 2:
                    a, b = int(nums[0]), int(nums[1])
                    for day_candidate, yr_candidate in [(a, b), (b, a)]:
                        if 1 <= day_candidate <= 31:
                            yr = yr_candidate + (2000 if yr_candidate < 70 else 1900)
                            try:
                                return _validate(yr, month_num, day_candidate)
                            except ValueError:
                                continue

            # Found month name, stop searching
            return None

    return None


